final class LazySeq<T> implements Iterable<T> {
    private final List<T> cache = new ArrayList<>();
    private Supplier<T> step;                    // null once the source is exhausted

    public Iterator<T> iterator() {
        return new Iterator<>() {
            private int i = 0;
            public boolean hasNext() { return i < cache.size() || force() != null; }
            public T next() { if (!hasNext()) throw new NoSuchElementException(); return cache.get(i++); }
            private T force() { T v = step == null ? null : step.get(); if (v == null) step = null; else cache.add(v); return v; }
        };
    }
}
